  ('stcse-2026-fdb71c9884eaa0e2a3ea1d54', '프로그래밍언어론', '109324', '본 강좌에서는 여러 프로그래밍 언어의 설계 목적과 기본 개념을 소개하고, 언어의 구성과 특성을 비교·분석하여 활용 가능성을 평가하는 방법을 학습한다.'),
  ('stcse-2026-f489b01929ee28951fa7d25b', '프로그래밍입문(1)', '109003', '본 강좌에서는 C 언어를 중심으로 프로그래밍의 기본 개념을 소개하고, 절차적인 문제 해결 과정을 프로그램으로 작성하고 구현하는 방법을 학습한다.'),
  ('stcse-2026-72952814843d7a0be199d034', '프로그래밍입문(2)', '109004', '본 강좌에서는 C++를 활용한 객체지향 프로그래밍의 기본 개념을 소개하고, 객체와 클래스, 캡슐화, 상속 및 다형성을 이용한 문제 해결 방법을 학습한다.'),
  ('stcse-2026-48f0c34a50a8cf78772900b8', '현장실습(1)', '109024', '본 강좌에서는 산업 현장의 기술 현황과 실제 업무를 접하고, 현장에서 활용되는 기술을 익혀 업무상의 문제를 해결하는 방법을 학습한다.'),
  ('stcse-2026-0f058f380d819419dfc049ca', '현장실습(3)', '109044', '본 강좌에서는 산업체의 기술과 업무 수행 과정을 현장에서 살펴보고, 실제 업무에 필요한 기술을 적용하여 문제를 해결하는 과정을 학습한다.'),
  ('stcse-2026-dd1ad00cc7f9f4753f8c7cd8', '형식언어및오토마타', '109084', '본 강좌에서는 형식언어와 문법체계의 기본 개념을 소개하고, 유한 오토마타와 푸시다운 오토마타 및 튜링 기계의 원리와 계산 복잡도의 관계를 학습한다.'),
  ('stcse-2026-8abca03565bd409781fbe044', '확률및랜덤변수', '109074', '본 강좌에서는 불규칙 신호를 이해하기 위한 확률변수와 확률 과정의 개념을 소개하고, 모멘트와 주요 확률 과정의 특성 및 선형 시스템 해석에 적용하는 방법을 학습한다.')
)
UPDATE catalog_courses AS cc SET recommendation_reason = authored.reason
FROM authored
WHERE cc.catalog_id = 'seoultech-cse-2026-major-v1'
  AND cc.course_id = authored.course_id
  AND cc.course_name = authored.course_name AND cc.course_code = authored.course_code;
